import pandas as pd, numpy as np
rY=np.load('/tmp/rY.npy'); rD=np.load('/tmp/rD.npy'); df=pd.read_csv('data.csv')
def theta(mask, y=rY, d=rD):
    yy=y[mask]; dd=d[mask]; t=(dd@yy)/(dd@dd)
    se=np.sqrt(np.sum(dd**2*(yy-t*dd)**2))/(dd@dd); return t,1.96*se,mask.sum()
print("== 异质性（局部线性 R-learner 斜率 dY/dD）==")
for name, var in [('region','region'),('tier','tier')]:
    for v in sorted(df[var].unique()):
        m=(df[var]==v).values; t,c,n=theta(m); print(f"{name}={v}: {t:7.4f} ±{c:.4f}  n={n}")
df['gmvq']=pd.qcut(df['log_pre_gmv'],4,labels=False)
for q in range(4):
    m=(df['gmvq']==q).values; t,c,n=theta(m); print(f"log_pre_gmv Q{q+1}(mean exp={np.exp(df['log_pre_gmv'][m].mean()):.1f}): {t:7.4f} ±{c:.4f} n={n}")
df['histq']=pd.qcut(df['log_hist_days'],4,labels=False)
for q in range(4):
    m=(df['histq']==q).values; t,c,n=theta(m); print(f"log_hist_days Q{q+1}: {t:7.4f} ±{c:.4f} n={n}")
df['ordq']=pd.qcut(df['orders'],4,labels=False,duplicates='drop')
for q in sorted(df['ordq'].unique()):
    m=(df['ordq']==q).values; t,c,n=theta(m); print(f"orders Q{q+1}: {t:7.4f} ±{c:.4f} n={n}")
m=np.ones(len(df),bool); t,c,n=theta(m); print(f"总体: {t:.4f} ±{c:.4f}")
